def resolve(path, cwd, links):
    # Check if path is absolute or relative
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Process remaining components after this one
            remaining = components[i+1:]

            # Parse the target
            if target.startswith('/'):
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Target is relative to the directory containing the link
                current = candidate.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
                target_components = target.split('/')

            # Continue resolution with target components and remaining components
            components = target_components + remaining
            i = 0
        else:
            current = candidate
            i += 1

    # Result has no trailing slash, except '/' itself
    if current == '/':
        return '/'
    else:
        return current

